INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 24, 'theory', 'Quiz: overview of the standard library');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 24, 0, 'Which layer of the standard library contains Vec and String but does not require an operating system?', '["core", "alloc", "std", "prelude"]', 1, 'alloc adds to core everything that needs a heap; std adds the OS on top.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 24, 1, 'What does the into_ prefix in a method name mean?', '["the method takes ownership of the value", "the method returns a reference", "the method checks a condition", "the method changes the value in place"]', 0, 'into_iter and into_boxed_slice take the value; as_ is a cheap reference; to_ is a new value.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 24, 2, 'How do you pull a value out of a field of &mut self, leaving an empty one in its place?', '["let x = self.field;", "self.field.clone().drop()", "std::mem::forget(self.field)", "std::mem::take(&mut self.field)"]', 3, 'mem::take takes the value and leaves Default; mem::replace puts in your own.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 24, 3, 'What does Option::ok_or(err) do?', '["turns a Result into an Option", "panics with the message err", "turns an Option into a Result, supplying the error for None", "returns a default value"]', 2, 'Some(x) becomes Ok(x), None becomes Err(err); after that you can use ?.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 24, 4, 'Why does “method not found” sometimes not mean the method is missing?', '["because the method is hidden in the documentation", "because the trait with this method is not imported with use", "because the compiler is out of date", "because the method is always private"]', 1, 'Trait methods are visible only if the trait is in scope (the prelude or a use).');
